import csv, json
from datetime import datetime, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from zoneinfo import ZoneInfo

inp = Path('/app/input')
order_dt = datetime(2026, 9, 25, 14, 40, tzinfo=ZoneInfo('America/Chicago'))
order_date = order_dt.date()
delivery_tax_key = ('Phenix City', 'AL')

catalogue = {}
with open(inp / 'cord_catalogue.csv', newline='') as f:
    for r in csv.DictReader(f):
        catalogue[r['sku']] = r

def codes_for(sku):
    return {sku, catalogue[sku]['supplier_part']}

store_rows = {}
with open(inp / 'store_directory.csv', newline='') as f:
    for r in csv.DictReader(f):
        store_rows.setdefault(r['store_id'], []).append(r)

def effective_store(store_id, date):
    rows = store_rows[store_id]
    eff = [r for r in rows if datetime.strptime(r['effective_from'], '%Y-%m-%d').date() <= date]
    return max(eff, key=lambda r: r['effective_from'])

stores = {sid: effective_store(sid, order_date) for sid in store_rows}

tax_rates = {}
with open(inp / 'tax_jurisdictions.csv', newline='') as f:
    for r in csv.DictReader(f):
        tax_rates[(r['city'], r['state'])] = Decimal(r['combined_sales_tax_pct'])

ledger = []
with open(inp / 'stock_ledger.csv', newline='') as f:
    for r in csv.DictReader(f):
        ledger.append(r)

def effective_stock(store_id, sku, order_local):
    codes = codes_for(sku)
    opening_qty = 0
    opening_time = None
    for r in ledger:
        if r['store_id'] != store_id or r['item_code'] not in codes:
            continue
        t = datetime.strptime(r['posted_local'], '%Y-%m-%d %H:%M')
        if t.date() == order_date and r['event'] == 'OPENING':
            if opening_time is None or t > opening_time:
                opening_time = t
                opening_qty = int(r['qty'])
    qty = opening_qty
    for r in ledger:
        if r['store_id'] != store_id or r['item_code'] not in codes:
            continue
        t = datetime.strptime(r['posted_local'], '%Y-%m-%d %H:%M')
        if t.date() != order_date or r['event'] == 'OPENING':
            continue
        if opening_time is not None and opening_time < t <= order_local:
            q = int(r['qty'])
            if r['event'] in ('RECEIPT', 'VOID'):
                qty += q
            elif r['event'] in ('SALE', 'HOLD', 'TRANSFER_OUT'):
                qty -= q
    return qty

def fit_reason(c):
    if c['connector'] != 'C7':
        return 'FIT_CONNECTOR'
    if c['polarized'] != 'N':
        return 'FIT_POLARIZED'
    length = int(c['length_ft'])
    awg = int(c['conductor_awg'])
    if length > 6 and awg > 18:
        return 'FIT_GAUGE'
    if length < 10 or length > 15:
        return 'FIT_LENGTH'
    return None

def cutoff_for(store_id, method, date):
    if method == 'PICKUP' and store_id == 'ST-08':
        return datetime(date.year, date.month, date.day, 16, 0)
    return datetime(date.year, date.month, date.day, 15, 0)

def method_paused(store_id, method, date):
    if store_id == 'ST-52' and method == 'DELIVERY':
        return True
    return False

def landed_cost(sku, store_id, method):
    c = catalogue[sku]
    price = Decimal(c['price_usd'])
    if method == 'PICKUP':
        rate = Decimal(stores[store_id]['sales_tax_pct'])
    else:
        rate = tax_rates[delivery_tax_key]
    total = price + price * rate / Decimal('100')
    total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    if method == 'DELIVERY':
        total += Decimal('9.99')
    return total

rows = []
with open(inp / 'same_day_offers.csv', newline='') as f:
    for offer in csv.DictReader(f):
        store_id = offer['store_id']
        sku = offer['sku']
        method = offer['method']
        store = stores[store_id]
        tz = ZoneInfo(store['timezone'])
        order_local = order_dt.astimezone(tz).replace(tzinfo=None)

        reason = fit_reason(catalogue[sku])
        if not reason:
            stock = effective_stock(store_id, sku, order_local)
            if stock < 1:
                reason = 'NO_STOCK'
            elif method == 'DELIVERY' and stock < 2:
                reason = 'STOCK_RESERVE'
            elif store['same_day_suspended'] == 'Y' or method_paused(store_id, method, order_date):
                reason = 'SAME_DAY_SUSPENDED'
            elif order_local >= cutoff_for(store_id, method, order_date):
                reason = 'CUTOFF_PASSED'
            elif method == 'DELIVERY' and Decimal(store['distance_mi']) > Decimal('10'):
                reason = 'OUT_OF_RADIUS'

        if reason:
            rows.append((offer['offer_id'], 'INELIGIBLE', reason, ''))
        else:
            rows.append((offer['offer_id'], 'ELIGIBLE', 'NONE', str(landed_cost(sku, store_id, method))))

with open('/app/offer_evaluation.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['offer_id', 'decision', 'reason_code', 'landed_cost_usd'])
    w.writerows(rows)

eligible = [r for r in rows if r[1] == 'ELIGIBLE']
eligible = [
    {
        'offer_id': r[0],
        'cost': Decimal(r[3]),
        'store_id': next(o['store_id'] for o in csv.DictReader(open(inp / 'same_day_offers.csv')) if o['offer_id'] == r[0]),
        'method': next(o['method'] for o in csv.DictReader(open(inp / 'same_day_offers.csv')) if o['offer_id'] == r[0]),
        'sku': next(o['sku'] for o in csv.DictReader(open(inp / 'same_day_offers.csv')) if o['offer_id'] == r[0]),
    }
    for r in eligible
]

def ready_time(o):
    store = stores[o['store_id']]
    tz = ZoneInfo(store['timezone'])
    local = order_dt.astimezone(tz)
    if o['method'] == 'PICKUP':
        return local + timedelta(hours=2)
    return local.replace(hour=20, minute=0, second=0, microsecond=0)

chosen = min(eligible, key=lambda o: (o['cost'], ready_time(o), Decimal(stores[o['store_id']]['distance_mi']), o['offer_id']))
with open('/app/results.json', 'w') as f:
    json.dump({
        'eligible_offer_count': len(eligible),
        'chosen_offer_id': chosen['offer_id'],
        'chosen_total_usd': float(chosen['cost']),
    }, f, indent=2)
    f.write('\n')
